#!/bin/zsh
# Builds the checklist widget into ~/.local/bin and restarts its LaunchAgents if loaded
# (one runs it in daily mode, the other with --weekly).
# Rerun this if you move this folder, so the widget can find its location files.
set -e
cd "$(dirname "$0")"
cat > BuildPaths.swift <<SWIFT
// Generated by build.sh; do not edit.
let projectDirectory = "$PWD"
SWIFT
# Build to a temp file and move it into place, so the running copies aren't overwritten mid-use.
swiftc -O -parse-as-library ChecklistWidget.swift BuildPaths.swift -o "$HOME/.local/bin/checklist-widget.new"
mv -f "$HOME/.local/bin/checklist-widget.new" "$HOME/.local/bin/checklist-widget"
echo "built $HOME/.local/bin/checklist-widget"
# Re-register each agent rather than just restarting it: launchd records the binary it's
# allowed to run, and refuses a rebuilt one ("Unable to get updated LWCR") until re-registered.
for label in com.haydenfletcher.checklistwidget com.haydenfletcher.weeklywidget; do
  plist="$HOME/Library/LaunchAgents/$label.plist"
  [ -f "$plist" ] || continue
  launchctl bootout "gui/$UID/$label" 2>/dev/null || true
  sleep 1
  launchctl bootstrap "gui/$UID" "$plist" && echo "restarted $label"
done
